//! Round-trip integration test against the real deployed keys.
//!
//! Loads keep/pk.bin + keep/vk.bin (generated by examples/keygen),
//! proves a projection with hus-sdk, encodes args as the contract will,
//! then verifies with the embedded-VK verifier logic that ships in the WASM.

use hus_sdk::circuit::r1cs::MAX_PROJ_DIM;
use hus_sdk::prover::prove_projected;
use hus_wasm_verifier::verify;

fn build_args(proof: &[u8], commitment: &[u8]) -> Vec<u8> {
    let mut args = Vec::with_capacity(4 + proof.len() + 32);
    args.extend_from_slice(&(proof.len() as u32).to_le_bytes());
    args.extend_from_slice(proof);
    args.extend_from_slice(commitment);
    args
}

#[test]
fn real_keys_roundtrip() {
    let pk_bytes = std::fs::read("../keep/pk.bin").expect("pk.bin missing — run examples/keygen");

    // Prove a valid projection.
    let v_obf: Vec<f32> = (0..MAX_PROJ_DIM).map(|i| (i as f32) / 100.0).collect();
    let (proof, commitment) = prove_projected(&pk_bytes, &v_obf).expect("prove failed");
    assert_eq!(commitment.len(), 32);
    assert_eq!(proof.len(), 128, "proof should be 128 bytes");

    // Verify via component logic.
    let args = build_args(&proof, &commitment);
    assert!(verify::verify(&args), "valid proof must verify");

    // Tamper with commitment -> must reject.
    let mut bad = build_args(&proof, &commitment);
    bad[4 + proof.len()] ^= 0x01;
    assert!(!verify::verify(&bad), "tampered commitment must reject");

    // Tamper with proof -> must reject.
    let mut bad = build_args(&proof, &commitment);
    bad[4] ^= 0x01;
    assert!(!verify::verify(&bad), "tampered proof must reject");

    // Malformed args -> reject without panic.
    assert!(!verify::verify(&[0u8; 4]));
    assert!(!verify::verify(&[]));
}